//! The DESK engineering knowledge, embedded as data with its provenance (M4.5, ADR-0062).
//!
//! `data/desk_knowledge.json` is generated by `scripts/gen-desk-domains.sh` from the owner's DESK
//! repository (`library/pcb_domains`, MIT, at the commit it records). It holds DESK's 66-rule
//! catalogue, the references those rules cite and the component families. All of it is
//! **knowledge, not EAK limits**:
//!
//! * every rule keeps DESK's own evidence state, and is shown no higher than
//!   [`Maturity::ceiling`] allows;
//! * DESK's rule parameters are DESK's working values; EAK applies none of them. EAK's checks use
//!   the project's declared constraints;
//! * a rule is linked to the EAK rules that evaluate a related concern ([`EAK_COVERAGE`]), or
//!   reported as not implemented in EAK;
//! * no reference stores copyrighted text, and none is verified (all `REFERENCE_ONLY`).
//!
//! [`validate`] is the loader check: it refuses a VERIFIED claim without a verified reference,
//! a dangling reference, archetype, overlay or family, a copied text, a duplicate id or a missing
//! licence or commit. It runs in the tests and in every tool answer.

use super::registry::{registry, Maturity};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeSet;
use std::sync::OnceLock;

const DATA: &str = include_str!("../../data/desk_knowledge.json");

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuleScope {
    #[serde(default)]
    pub archetypes: Vec<String>,
    #[serde(default)]
    pub overlays: Vec<String>,
    #[serde(default)]
    pub component_families: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum DeskSeverity {
    Blocking,
    Error,
    Warning,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum EnforcementMode {
    Enforced,
    Advisory,
    Unsupported,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Enforcement {
    pub subsystem: String,
    pub mode: EnforcementMode,
}

/// One rule of the DESK catalogue.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DeskRule {
    pub rule_id: String,
    pub name: String,
    pub version: String,
    pub domain: String,
    pub category: String,
    pub scope: RuleScope,
    pub severity: DeskSeverity,
    pub applicability: Value,
    pub required_inputs: Vec<String>,
    pub evaluation_method: String,
    /// DESK's working values. EAK applies none of them.
    pub parameters: Value,
    pub source_references: Vec<String>,
    pub verification_method: String,
    /// DESK's evidence state.
    pub status: Maturity,
    pub enforcement: Enforcement,
    pub human_review_required: bool,
    pub rationale: String,
}

/// A source a DESK rule cites. Only bibliographic data: no text of the source is stored.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Reference {
    pub id: String,
    pub title: String,
    pub organisation: String,
    pub kind: String,
    pub clause_notes: String,
    pub url: String,
    pub derived_values_used: Vec<String>,
    /// `REFERENCE_ONLY` for every reference DESK ships: nobody compared the values with the text.
    pub verification_status: String,
    pub copyrighted_text_stored: bool,
}

/// A DESK component family (an engineering role, not a part).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Family {
    pub family_id: String,
    pub name: String,
    pub group: String,
    pub description: String,
    pub required_parameters: Vec<String>,
    pub datasheet_verification: Vec<String>,
    pub relevant_archetypes: Vec<String>,
    pub aliases: Vec<String>,
}

#[derive(Debug, Deserialize)]
pub struct Knowledge {
    pub source: String,
    pub licence: String,
    pub desk_commit: String,
    pub rules: Vec<DeskRule>,
    pub references: Vec<Reference>,
    pub families: Vec<Family>,
}

impl Knowledge {
    pub fn rule(&self, id: &str) -> Option<&DeskRule> {
        self.rules.iter().find(|r| r.rule_id == id)
    }
    pub fn reference(&self, id: &str) -> Option<&Reference> {
        self.references.iter().find(|r| r.id == id)
    }
    pub fn family(&self, id: &str) -> Option<&Family> {
        self.families.iter().find(|f| f.family_id == id)
    }
}

/// The embedded knowledge. Generated and validated data: a parse failure is a build defect.
pub fn knowledge() -> &'static Knowledge {
    static K: OnceLock<Knowledge> = OnceLock::new();
    K.get_or_init(|| {
        serde_json::from_str(DATA).expect("embedded desk_knowledge.json is generated and validated")
    })
}

/// DESK rules and the EAK rules (`eak_validation`) that evaluate a related concern. A related
/// rule's scope and parameters may differ from DESK's; a DESK rule not listed is not implemented
/// in EAK.
#[rustfmt::skip]
pub const EAK_COVERAGE: &[(&str, &[&str])] = &[
    ("COPPER-ANT-045", &["DRC-021"]),
    ("COPPER-BARRIER-044", &["DRC-021"]),
    ("COPPER-ISLAND-043", &["DRC-013"]),
    ("COPPER-RELIEF-042", &["DRC-014"]),
    ("ELEC-CLEAR-003", &["DRC-002"]),
    ("ELEC-DROP-006", &["DRC-028"]),
    ("ELEC-RATING-007", &["ERC-011", "ERC-022", "ERC-023", "ERC-024"]),
    ("ELEC-VIA-005", &["DRC-027"]),
    ("ELEC-WIDTH-001", &["DRC-008"]),
    ("MCU-USB-102", &["DRC-024", "DRC-025", "DRC-026"]),
    ("MFG-DRILL-071", &["DRC-006"]),
    ("MFG-EDGE-072", &["DRC-005"]),
    ("MFG-MIN-070", &["DFM-001", "DFM-002"]),
    ("PLACE-DECAP-010", &["ERC-010"]),
    ("PLACE-KEEPOUT-011", &["DRC-021"]),
    ("ROUTE-DIFF-021", &["DRC-024", "DRC-025", "DRC-026"]),
    ("ROUTE-HV-025", &["DRC-021"]),
    ("THERM-TJ-050", &["ERC-025"]),
];

/// The EAK rules related to a DESK rule (empty: not implemented in EAK).
pub fn eak_rules(desk_rule: &str) -> &'static [&'static str] {
    for (d, e) in EAK_COVERAGE {
        if *d == desk_rule {
            return e;
        }
    }
    &[]
}

/// How a DESK rule stands in EAK, for display.
#[derive(Debug, Clone, Serialize)]
pub struct RuleView<'a> {
    pub rule: &'a DeskRule,
    /// What EAK may say about it (DESK's evidence state caps the claim).
    pub claim: &'static str,
    pub may_present_as_requirement: bool,
    pub eak_rules: &'static [&'static str],
    /// `RELATED_EAK_RULES` or `NOT_IMPLEMENTED_IN_EAK`.
    pub eak_state: &'static str,
    pub references: Vec<&'a Reference>,
}

pub fn view(rule: &DeskRule) -> RuleView<'_> {
    let ceiling = rule.status.ceiling();
    let eak = eak_rules(&rule.rule_id);
    let k = knowledge();
    RuleView {
        rule,
        claim: ceiling.claim,
        may_present_as_requirement: ceiling.may_present_as_requirement,
        eak_rules: eak,
        eak_state: if eak.is_empty() {
            "NOT_IMPLEMENTED_IN_EAK"
        } else {
            "RELATED_EAK_RULES"
        },
        references: rule
            .source_references
            .iter()
            .filter_map(|id| k.reference(id))
            .collect(),
    }
}

fn verified(m: Maturity) -> bool {
    matches!(m, Maturity::VerifiedAgainstSource | Maturity::LiveVerified)
}

/// Loader check over `k` (see the module documentation). Empty when the data is sound.
pub fn validate(k: &Knowledge) -> Vec<String> {
    let mut found = vec![];
    if k.licence != "MIT" {
        found.push(format!("licence is {:?}, expected MIT", k.licence));
    }
    if k.desk_commit.len() != 40 || !k.desk_commit.bytes().all(|b| b.is_ascii_hexdigit()) {
        found.push(format!(
            "desk_commit {:?} is not a commit hash",
            k.desk_commit
        ));
    }
    let reg = registry();
    let refs: BTreeSet<&str> = k.references.iter().map(|r| r.id.as_str()).collect();
    let families: BTreeSet<&str> = k.families.iter().map(|f| f.family_id.as_str()).collect();
    let mut ids = BTreeSet::new();
    for r in &k.rules {
        if !ids.insert(r.rule_id.as_str()) {
            found.push(format!("{}: duplicate rule id", r.rule_id));
        }
        for a in &r.scope.archetypes {
            if a != "*" && reg.archetype(a).is_none() {
                found.push(format!("{}: unknown archetype {a}", r.rule_id));
            }
        }
        for o in &r.scope.overlays {
            if reg.overlay(o).is_none() {
                found.push(format!("{}: unknown overlay {o}", r.rule_id));
            }
        }
        for f in &r.scope.component_families {
            if !families.contains(f.as_str()) {
                found.push(format!("{}: unknown component family {f}", r.rule_id));
            }
        }
        for s in &r.source_references {
            if !refs.contains(s.as_str()) {
                found.push(format!("{}: unknown reference {s}", r.rule_id));
            }
        }
        // DESK policy: a VERIFIED claim needs every cited source verified by a person.
        if verified(r.status) {
            let unverified = r.source_references.iter().any(|s| {
                k.reference(s)
                    .is_none_or(|x| x.verification_status != "VERIFIED")
            });
            if unverified || r.source_references.is_empty() {
                found.push(format!(
                    "{}: claims {:?} but its sources are not verified",
                    r.rule_id, r.status
                ));
            }
        }
    }
    for r in &k.references {
        if r.copyrighted_text_stored {
            found.push(format!("reference {}: stores copyrighted text", r.id));
        }
    }
    let mut fids = BTreeSet::new();
    for f in &k.families {
        if !fids.insert(f.family_id.as_str()) {
            found.push(format!("family {}: duplicate id", f.family_id));
        }
        for a in &f.relevant_archetypes {
            if reg.archetype(a).is_none() {
                found.push(format!("family {}: unknown archetype {a}", f.family_id));
            }
        }
    }
    for a in &reg.archetypes {
        for id in &a.maturity.rule_ids {
            if k.rule(id).is_none() {
                found.push(format!("archetype {}: unknown rule {id}", a.archetype_id));
            }
        }
    }
    for (d, e) in EAK_COVERAGE {
        if k.rule(d).is_none() {
            found.push(format!("EAK_COVERAGE: unknown DESK rule {d}"));
        }
        for id in *e {
            if !eak_core::known_rule_id(id) {
                found.push(format!("EAK_COVERAGE {d}: unknown EAK rule {id}"));
            }
        }
    }
    found
}

#[cfg(test)]
mod tests {
    use super::*;

    /// DESK `library/pcb_domains` at the recorded commit: 66 rules, 46 references, 206 families.
    #[test]
    fn the_embedded_knowledge_is_complete_and_sound() {
        let k = knowledge();
        assert_eq!(k.rules.len(), 66);
        assert_eq!(k.references.len(), 46);
        assert_eq!(k.families.len(), 206);
        assert_eq!(validate(k), Vec::<String>::new());
    }

    /// Ported from DESK `test_rule_provenance.py::test_no_rule_claims_verification_against_source_yet`.
    #[test]
    fn no_rule_claims_verification_against_its_source() {
        let k = knowledge();
        assert!(k.rules.iter().all(|r| !verified(r.status)));
        assert!(k.rules.iter().all(|r| !view(r).may_present_as_requirement));
        assert!(k
            .references
            .iter()
            .all(|r| r.verification_status == "REFERENCE_ONLY" && !r.copyrighted_text_stored));
    }

    #[test]
    fn the_loader_refuses_an_unsupported_verified_claim_and_dangling_links() {
        let mut k: Knowledge = serde_json::from_str(DATA).unwrap();
        k.rules[0].status = Maturity::VerifiedAgainstSource;
        k.rules[1].source_references.push("NO-SUCH-REF".into());
        k.references[0].copyrighted_text_stored = true;
        k.licence = "GPL-3.0".into();
        let found = validate(&k).join("\n");
        assert!(
            found.contains("but its sources are not verified"),
            "{found}"
        );
        assert!(found.contains("unknown reference NO-SUCH-REF"), "{found}");
        assert!(found.contains("stores copyrighted text"), "{found}");
        assert!(found.contains("expected MIT"), "{found}");
    }

    #[test]
    fn coverage_links_desk_rules_to_real_eak_rules_and_leaves_the_rest_unimplemented() {
        let k = knowledge();
        let width = view(k.rule("ELEC-WIDTH-001").unwrap());
        assert_eq!(width.eak_rules, ["DRC-008"]);
        assert_eq!(width.eak_state, "RELATED_EAK_RULES");
        assert!(width.references.iter().any(|r| r.id == "IPC-2221B"));
        let creep = view(k.rule("ELEC-CREEP-004").unwrap());
        assert_eq!(creep.eak_state, "NOT_IMPLEMENTED_IN_EAK");
        assert!(creep.eak_rules.is_empty());
    }
}
